CREATE TABLE "projects" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, "description" character varying NOT NULL DEFAULT '', "scm_type" character varying NOT NULL DEFAULT 'git', "scm_url" character varying NOT NULL DEFAULT '', "scm_branch" character varying NOT NULL DEFAULT '', "local_path" character varying NOT NULL DEFAULT '', "revision" character varying NOT NULL DEFAULT '', "sync_status" character varying NOT NULL DEFAULT 'never', "sync_error" character varying NOT NULL DEFAULT '', "last_synced_at" timestamptz NULL, "credential_projects" bigint NULL, "organization_projects" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "projects_credentials_projects" FOREIGN KEY ("credential_projects") REFERENCES "credentials" ("id") ON DELETE SET NULL, CONSTRAINT "projects_organizations_projects" FOREIGN KEY ("organization_projects") REFERENCES "organizations" ("id") ON DELETE NO ACTION);
CREATE UNIQUE INDEX "project_name_organization_projects" ON "projects" ("name", "organization_projects");
ALTER TABLE "templates" ADD COLUMN "project_templates" bigint NULL, ADD CONSTRAINT "templates_projects_templates" FOREIGN KEY ("project_templates") REFERENCES "projects" ("id") ON DELETE SET NULL;
